import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const [stream, setStream] = useState(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");   // Une seule string pour tout afficher

  // Démarrer la caméra
  useEffect(() => {
    let mediaStream = null;

    const start = async () => {
      try {
        mediaStream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: 1280, height: 720 }
        });
        setStream(mediaStream);
        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
      } catch (err) {
        setStatus("❌ Impossible d'accéder à la caméra");
      }
    };

    start();

    return () => {
      if (mediaStream) {
        mediaStream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  // Stop caméra
  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setStatus("📴 Caméra arrêtée");
  };

  // Capture
  const handleCapture = useCallback(async () => {
    if (!videoRef.current) return;

    setLoading(true);
    setStatus("⏳ Analyse en cours...");

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageSrc = canvas.toDataURL('image/jpeg');

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = (Number(data.confidence || 0) * 100).toFixed(1);

      if (data.success || name !== "Inconnu") {
        setStatus(`✅ ${name} - Confiance : ${confidence}%`);
      } else {
        setStatus(`⚠️ ${String(data.message || data.error || "Visage non reconnu")}`);
      }
    } catch (err) {
      setStatus(`❌ ${err.message || "Erreur serveur"}`);
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto', textAlign: 'center' }}>
      <h1>📷 Reconnaissance Faciale</h1>

      <div style={{ borderRadius: '16px', overflow: 'hidden', background: '#000', margin: '30px 0' }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: '100%', height: 'auto' }}
        />
      </div>

      <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
        <button 
          onClick={handleCapture}
          disabled={loading}
          style={{ flex: 1, padding: '16px', fontSize: '17px', background: '#4F46E5', color: 'white', border: 'none', borderRadius: '10px' }}
        >
          {loading ? '⏳ Analyse...' : '🔍 Capturer & Analyser'}
        </button>

        <button 
          onClick={stopCamera}
          style={{ flex: 1, padding: '16px', fontSize: '17px', background: '#EF4444', color: 'white', border: 'none', borderRadius: '10px' }}
        >
          🛑 Arrêter la Caméra
        </button>
      </div>

      {status && (
        <div style={{
          padding: '20px',
          borderRadius: '12px',
          fontSize: '19px',
          background: status.includes('✅') ? '#DCFCE7' : '#FEE2E2',
          color: status.includes('✅') ? '#166534' : '#991B1B'
        }}>
          {status}
        </div>
      )}
    </div>
  );
};

export default CameraRecognition;
